    "seo.header.title": "The Ultimate Free PDF Toolkit with Zero Server Uploads",
    "seo.header.subtitle": "TacoPDF: 100% Secure, Fast & Private Browser-Based PDF Editor, Merger, Splitter, and Protection",
    "seo.box1.title": "100% Local Processing",
    "seo.box1.desc": "Your documents are never sent over the internet or stored on a cloud server. All editing, merging, and encryption processes are executed directly inside your web browser using local memory.",
    "seo.box2.title": "WebAssembly Technology",
    "seo.box2.desc": "Powered by high-performance WebAssembly (Wasm) compiled engine binaries, even extremely large PDF files are processed instantly in milliseconds. No slow upload or download times required.",
    "seo.box3.title": "Fully Free & Offline",
    "seo.box3.desc": "Completely free to use with no daily usage limits or paid subscription barriers. Simply load the page once, and you can continue processing your PDFs offline without an internet connection.",
    "seo.secure.title": "Secure PDF Document Optimization Without Any Security Risks",
    "seo.secure.p1": "In today's digital landscape, PDF documents often contain highly sensitive data such as financial balance sheets, scanned personal identity documents (IDs, Passports, SSNs), legal contracts, and medical records. Using typical online converters forces you to entrust your precious documents to third-party cloud servers, exposing you to data breach vulnerabilities.",
    "seo.secure.p2": "<strong className=\"text-primary font-semibold\">TacoPDF</strong> establishes a new standard in digital file management. By compiling the entire processing engine locally, we guarantee that your files remain completely in your hands. This is the most secure and private way to edit, split, merge, and optimize documents without touching the internet.",
    "seo.features.title": "Outstanding Features Tailored for Your Document Productivity",
    "seo.features.merge": "Combine multiple report sheets or slides into a single concise PDF document seamlessly.",
    "seo.features.split": "Extract specific crucial pages to create a fresh PDF document in an instant.",
    "seo.features.rotate": "Correct upside-down scans by rotating specific pages exactly as needed.",
    "seo.features.protect": "Lock and encrypt sensitive PDF files locally using secure, standard AES algorithms.",
    "seo.features.unlock": "Strip away passwords from your own documents for easier printing and sharing.",
    "seo.features.redact": "Permanently black out and censor sensitive text or images to protect confidential information.",
    "seo.features.image_to_pdf": "Instantly convert PNG, JPG, JPEG, and WebP images into formal print-ready PDF files.",
    "seo.features.pdf_to_image": "Extract and render each page of your PDF into high-quality image photos.",
    "seo.features.delete_pages": "Slice away blank or unwanted pages from your document structure cleanly.",
    "seo.features.extract_pages": "Pick only the pages you want to keep and save them as a lightweight file.",
    "seo.features.add_watermark": "Secure scanned IDs, receipts, or drafts with fully customizable diagonal text overlays.",
    "seo.features.add_page_numbers": "Stamp custom numbering formats and dynamic page counts seamlessly onto your pages.",
