    "tool.redact.edit_page": "Edit Halaman",
    "tool.redact.done_edit": "Selesai Edit",
    "faq.1.q": "Apakah aman memproses file PDF di sini?",
    "faq.1.a": "Tentu saja. Semua file diproses secara lokal di memori browser Anda menggunakan modul WebAssembly berkinerja tinggi. Tidak ada satu byte pun dari dokumen Anda yang pernah diunggah atau dikirim ke server kami. Dokumen Anda tetap sepenuhnya aman di perangkat Anda sendiri.",
    "faq.2.q": "Apakah TacoPDF benar-benar 100% gratis?",
    "faq.2.a": "Ya, sepenuhnya gratis tanpa biaya tersembunyi, tanpa perlu mendaftar akun, tanpa watermark paksa, dan tanpa batasan jumlah file harian. Untuk menutupi biaya operasional peladen (server), kami hanya menampilkan sedikit iklan sponsor dan menerima dukungan berupa donasi sukarela dari pengguna.",
    "faq.3.q": "Bisakah saya menggunakan alat ini offline tanpa internet?",
    "faq.3.a": "Bisa! Setelah aplikasi web dimuat di browser Anda untuk pertama kalinya, semua logika pemrosesan PDF berjalan sepenuhnya di sisi klien. Anda dapat memutuskan koneksi internet dengan aman dan melanjutkan proses secara offline penuh.",
    "faq.4.q": "Mengapa website ini menampilkan iklan?",
    "faq.4.a": "Sebagai alat utilitas publik yang mengutamakan keamanan tanpa membebankan biaya langganan, iklan sponsor membantu mendanai infrastruktur dasar kami. Kami menempatkan iklan agar tidak mengganggu, nyaman dilihat, dan terpisah dari ruang kerja aktif Anda.",
    "faq.5.q": "Format file apa saja yang didukung?",
    "faq.5.a": "TacoPDF mendukung dokumen PDF standar (dari versi 1.0 hingga standar terbaru), serta format file gambar populer seperti PNG, JPG, JPEG, dan WebP untuk diubah menjadi dokumen PDF.",
    "faq.6.q": "Apakah dengan berdonasi saya akan mendapatkan fitur premium?",
    "faq.6.a": "Tidak. TacoPDF berkomitmen untuk menyediakan semua alat PDF secara gratis untuk semua orang tanpa terkecuali. Donasi Anda murni bersifat dukungan sukarela agar kami bisa terus membayar biaya peladen dan mengembangkan fitur baru. Tidak ada fitur rahasia yang dikunci di balik pembayaran.",
    "faq.7.q": "Apakah data pembayaran donasi saya aman?",
    "faq.7.a": "Sangat aman. Kami menggunakan platform pihak ketiga yang terpercaya, yaitu Saweria (untuk Indonesia) dan Ko-Fi (Internasional), sebagai gerbang pembayaran. TacoPDF sama sekali tidak melihat, memproses, atau menyimpan nomor kartu kredit atau detail perbankan Anda di server kami.",
