    "contact.faq1_q": "¿Tacopdf guarda mis archivos PDF?",
    "contact.faq1_a": "No. Todo el procesamiento se realiza localmente en su navegador. Sus archivos nunca se suben a nuestros servidores.",
    "contact.faq2_q": "¿Las herramientas de Tacopdf son realmente gratuitas?",
    "contact.faq2_a": "Sí, todas nuestras herramientas son de uso gratuito. Usamos anuncios no intrusivos para cubrir costos operativos.",

    "tool.redact.howto.1": "Sube el PDF que contiene información confidencial.",
    "tool.redact.howto.2": "Dibuja rectángulos negros sobre el texto o las imágenes que deseas censurar.",
    "tool.redact.howto.3": "Haz clic en 'Ejecutar Redactar' para aplicar el bloqueo permanente.",
    "tool.redact.howto.4": "Descarga la versión censurada de forma segura.",
    "tool.redact.tips.1": "Una vez redactado, el texto subyacente se elimina por completo y no se puede recuperar.",
    "tool.redact.tips.2": "Revisa siempre tus censuras en la vista previa antes de guardar el documento final.",
    "tool.redact.clear_page": "Borrar Página",
    "tool.redact.edit_page": "Editar Página",
    "tool.redact.done_edit": "Edición Terminada",
    "faq.1.q": "¿Es seguro procesar archivos PDF aquí?",
    "faq.1.a": "Absolutamente. Todos los archivos se procesan localmente en la memoria de su navegador utilizando módulos WebAssembly de alto rendimiento. Ni un solo byte de sus documentos es subido o enviado a nuestros servidores.",
    "faq.2.q": "¿Es TacoPDF verdaderamente 100% gratuito?",
    "faq.2.a": "Sí, es completamente gratis sin costos ocultos, sin necesidad de registrar una cuenta, sin marcas de agua forzadas y sin límites diarios de archivos. Para cubrir los costos operativos del servidor, solo mostramos algunos anuncios patrocinados y aceptamos donaciones voluntarias de nuestros usuarios.",
    "faq.3.q": "¿Puedo usar esta herramienta sin internet?",
    "faq.3.a": "¡Sí! Una vez que la aplicación web se carga en su navegador por primera vez, toda la lógica de procesamiento funciona completamente en el lado del cliente. Puede desconectar su internet y continuar usándolo.",
    "faq.4.q": "¿Por qué este sitio web muestra anuncios?",
    "faq.4.a": "Como herramienta pública gratuita, los anuncios de ayudan a financiar nuestra infraestructura básica. Optimizamos la ubicación de los anuncios para que no sean molestos.",
    "faq.5.q": "¿Qué formatos de archivo son compatibles?",
    "faq.5.a": "TacoPDF admite cualquier documento PDF estándar, así como formatos de archivo de imagen populares como PNG, JPG, JPEG y WebP para convertirlos en documentos PDF de calidad.",
    "faq.6.q": "¿Donar me dará acceso a funciones premium?",
    "faq.6.a": "No. TacoPDF se compromete a proporcionar todas las herramientas PDF de forma gratuita a todos sin excepción. Su donación es un apoyo puramente voluntario para que podamos seguir pagando los costos del servidor y desarrollando nuevas funciones. No hay funciones secretas bloqueadas tras un muro de pago.",
    "faq.7.q": "¿Están seguros mis datos de pago de donación?",
    "faq.7.a": "Muy seguros. Utilizamos plataformas de terceros de confianza, concretamente Saweria (para Indonesia) y Ko-Fi (Internacional), como pasarelas de pago. TacoPDF no ve, procesa ni almacena en absoluto sus números de tarjeta de crédito o datos bancarios en nuestros servidores.",
