    "tool.delete-pages.tip.title": "🗑️ ELIMINAR EN BLANCO",
    "tool.delete-pages.tip.desc": "Deshágase de las portadas innecesarias o las páginas en blanco al final del documento para que su archivo se vea más ordenado y profesional.",
    "tool.extract-pages.tip.title": "🎯 ENFOQUE CENTRAL",
    "tool.extract-pages.tip.desc": "A diferencia de la función de eliminación, esta le permite filtrar y elegir solo páginas específicas para crear un PDF completamente nuevo.",
    "tool.protect.tip.title": "🔒 CIFRADO MILITAR",
    "tool.protect.tip.desc": "Su contraseña está bloqueada con un fuerte estándar de algoritmo. No almacenamos esta contraseña, ¡así que asegúrese de no olvidarla!",
    "tool.unlock.tip.title": "🔓 DESBLOQUEAR UNA VEZ",
    "tool.unlock.tip.desc": "Elimine la capa de cifrado de su documento para no tener que volver a escribir la contraseña cada vez que abra el archivo.",
    "tool.sign.tip.title": "✍️ FIRMA WYSIWYG",
    "tool.sign.tip.desc": "Arrastre su firma con precisión a la línea deseada. ¡Lo que ve en la pantalla es lo que obtiene!",
    "tool.redact.tip.title": "⬛ CENSURA PERMANENTE",
    "tool.redact.tip.desc": "¡Esta caja no es solo una pegatina negra! Elimina permanentemente los datos de texto detrás de ella para que ya no se puedan copiar y pegar.",
    "tool.image-to-pdf.tip.title": "🖼️ IMAGEN A PDF",
    "tool.image-to-pdf.tip.desc": "¡Sube imágenes JPG, PNG o WEBP — varias a la vez! Arrastra las tarjetas para reordenarlas antes de convertir. Elige el tamaño de página: A4, Carta o Ajustar a imagen.",
    "tool.pdf-to-image.tip.title": "🖼️ IDEAL PARA REDES SOCIALES",
    "tool.pdf-to-image.tip.desc": "Los archivos PDF no se pueden publicar en feeds sociales. ¡Convierta a JPG/PNG de alta resolución aquí para que se puedan compartir fácilmente!",
    "tool.html-to-pdf.tip.title": "🌐 FACTURAS Y RECIBOS",
    "tool.html-to-pdf.tip.desc": "Muy útil para pegar códigos de recibos sin procesar o artículos web y convertirlos en documentos PDF listos para imprimir.",
    "tool.add-watermark.tip.title": "©️ PROTEJA SU TRABAJO",
    "tool.add-watermark.tip.desc": "Use un nivel bajo de transparencia (opacidad) para que el sello de derechos de autor proteja el documento sin interrumpir el contenido de texto original.",
    "tool.add-page-numbers.tip.title": "🔢 ESTÁNDAR OFICIAL",
    "tool.add-page-numbers.tip.desc": "La mayoría de las instituciones y universidades requieren números de página en esquinas específicas de los documentos. ¡Hágalo con un clic aquí!",
