    "seo.header.title": "El Mejor Kit de Herramientas PDF Gratuito sin Subidas al Servidor",
    "seo.header.subtitle": "TacoPDF: Editor y Optimizador PDF Basado en Navegador 100% Seguro, Rápido y Privado",
    "seo.box1.title": "100% Procesamiento Local",
    "seo.box1.desc": "Tus documentos nunca se envían por internet ni se almacenan en un servidor en la nube. Todo ocurre directamente en tu navegador web.",
    "seo.box2.title": "Tecnología WebAssembly",
    "seo.box2.desc": "Impulsado por motores WebAssembly (Wasm) de alto rendimiento, los archivos se procesan al instante. Sin tiempos de espera.",
    "seo.box3.title": "Totalmente Gratis y Offline",
    "seo.box3.desc": "Completamente gratis sin límites de uso. Carga la página una vez y continúa procesando sin conexión a internet.",
    "seo.secure.title": "Optimización Segura de PDF Sin Riesgos",
    "seo.secure.p1": "Usar convertidores en línea típicos te obliga a confiar tus documentos a servidores de terceros, exponiéndote a vulnerabilidades.",
    "seo.secure.p2": "<strong className=\"text-primary font-semibold\">TacoPDF</strong> garantiza que tus archivos permanezcan en tus manos. Es la forma más segura de gestionar documentos.",
    "seo.features.title": "Características Destacadas para tu Productividad",
    "seo.features.merge": "Combina múltiples hojas de informes en un solo documento PDF.",
    "seo.features.split": "Extrae páginas cruciales específicas para crear un PDF nuevo al instante.",
    "seo.features.rotate": "Corrige escaneos invertidos rotando páginas específicas exactamente como se necesita.",
    "seo.features.protect": "Bloquea y encripta archivos PDF sensibles localmente usando algoritmos AES seguros.",
    "seo.features.unlock": "Elimina contraseñas de tus propios documentos para facilitar la impresión y el intercambio.",
    "seo.features.redact": "Oculte y censure permanentemente texto o imágenes confidenciales para proteger la información.",
    "seo.features.image_to_pdf": "Convierte imágenes PNG, JPG, JPEG y WebP en archivos PDF formales listos para imprimir al instante.",
    "seo.features.pdf_to_image": "Extrae y renderiza cada página de tu PDF en fotos de imágenes de alta qualidade.",
    "seo.features.delete_pages": "Elimina páginas en blanco o no deseadas de la estructura de tu documento limpiamente.",
    "seo.features.extract_pages": "Elige solo las páginas que deseas conservar y guárdalas como un archivo ligero.",
    "seo.features.add_watermark": "Asegura identificaciones escaneadas, recibos ou borradores com sobreposições de texto diagonal totalmente personalizáveis.",
    "seo.features.add_page_numbers": "Estampa formatos de numeración personalizados e recuentos dinámicos de páginas en tus páginas.",
