    "faq.1.q": "ここで PDF ファイルを処理しても安全ですか?",
    "faq.1.a": "絶対に。 すべてのファイルは、高性能 WebAssembly モジュールを使用して Web ブラウザのメモリ内でローカルに処理されます。 あなたの文書は 1 バイトも当社のサーバーにアップロードまたは送信されることはありません。 ビジネス、個人、機密の機密記録は、自分のデバイス上で完全に安全に保たれます。",
    "faq.2.q": "TacoPDF は本当に完全に無料ですか?",
    "faq.2.a": "はい、隠れた費用、アカウント登録の必要性、強制的な透かし、および1日のファイル制限なしに完全に無料です。サーバーの運営費を賄うために、わずかなスポンサー広告を表示し、ユーザーからの任意の寄付を受け付けています。",
    "faq.3.q": "このツールキットはインターネットなしでオフラインで使用できますか?",
    "faq.3.a": "はい！ Web アプリケーションが初めてブラウザーに読み込まれると、すべての PDF 処理ロジックが完全にクライアント側で実行されます。 インターネットを安全に切断しても、PDF ファイルの結合、分割、回転、保護を完全にオフラインで続行できます。",
    "faq.4.q": "なぜこの Web サイトに広告が表示されるのですか?",
    "faq.4.a": " のスポンサー広告は、サブスクリプション料金を請求せずにセキュリティを重視する公共の実用性の高いツールとして、基本的なインフラストラクチャの資金調達に役立ちます。 邪魔にならず、目に優しく、アクティブなワークスペースから完全に分離されるように、広告の配置を最適化します。",
    "faq.5.q": "どのようなファイル形式がサポートされていますか?",
    "faq.5.a": "TacoPDF は、標準的な PDF ドキュメント (バージョン 1.0 から最新の標準まで) に加え、PNG、JPG、JPEG、WebP などの一般的な画像ファイル形式をサポートし、プロ仕様の PDF ドキュメントにコンパイルします。",
    "faq.6.q": "寄付をするとプレミアム機能にアクセスできますか？",
    "faq.6.a": "いいえ。TacoPDFは、例外なくすべての人にすべてのPDFツールを無料で提供することをお約束します。皆様からの寄付は、当社がサーバー費用を支払い、新機能を開発し続けるための純粋な任意の支援です。支払いの背後に隠された秘密の機能はありません。",
    "faq.7.q": "寄付の支払いデータは安全ですか？",
    "faq.7.a": "非常に安全です。当社は、支払いゲートウェイとして、信頼できるサードパーティのプラットフォームであるSaweria（インドネシア向け）およびKo-Fi（国際向け）を使用しています。TacoPDFが当社のサーバー上でお客様のクレジットカード番号や銀行の詳細を確認、処理、または保存することは一切ありません。",
