    "seo.box2.desc": "高性能の WebAssembly (Wasm) コンパイル エンジン バイナリを搭載しており、非常に大きな PDF ファイルであっても数ミリ秒以内に即座に処理されます。 アップロードやダウンロードに時間がかかる必要はありません。",
    "seo.box3.title": "完全無料＆オフライン",
    "seo.box3.desc": "1 日の使用制限や有料サブスクリプションの障壁がなく、完全に無料で使用できます。 ページを一度ロードするだけで、インターネット接続なしでオフラインで PDF の処理を​​続けることができます。",
    "seo.secure.title": "セキュリティリスクのない安全な PDF ドキュメントの最適化",
    "seo.secure.p1": "今日のデジタル環境では、PDF ドキュメントには、財務貸借対照表、スキャンされた個人識別書類 (ID、パスポート、SSN)、法的契約書、医療記録などの非常に機密性の高いデータが含まれることがよくあります。 一般的なオンライン コンバータを使用すると、貴重なドキュメントをサードパーティのクラウド サーバーに預けることになり、データ侵害の脆弱性にさらされることになります。",
    "seo.secure.p2": "<strong className=\\\"text-primary font-semibold\\\">TacoPDF</strong> は、デジタル ファイル管理の新しい標準を確立します。 処理エンジン全体をローカルでコンパイルすることで、ファイルが完全に手元に残ることが保証されます。 これは、インターネットに接続せずにドキュメントを編集、分割、結合、最適化するための最も安全でプライベートな方法です。",
    "seo.features.title": "ドキュメントの生産性に合わせた優れた機能",
    "seo.features.merge": "複数のレポート シートまたはスライドを 1 つの簡潔な PDF ドキュメントにシームレスに結合します。",
    "seo.features.split": "特定の重要なページを抽出して、新しい PDF ドキュメントを瞬時に作成します。",
    "seo.features.rotate": "必要に応じて特定のページを正確に回転して、逆さまのスキャンを修正します。",
    "seo.features.protect": "安全な標準 AES アルゴリズムを使用して、機密 PDF ファイルをローカルでロックおよび暗号化します。",
    "seo.features.unlock": "自分の文書からパスワードを削除して、印刷や共有を容易にします。",
    "seo.features.redact": "機密情報を保護するために、機密性の高いテキストや画像を永久に黒く塗りつぶして検閲します。",
    "seo.features.image_to_pdf": "PNG、JPG、JPEG、および WebP 画像を、印刷可能な正式な PDF ファイルに即座に変換します。",
    "seo.features.pdf_to_image": "PDF の各ページを抽出して、高品質の画像写真にレンダリングします。",
    "seo.features.delete_pages": "空白のページや不要なページを文書構造からきれいに切り取ります。",
    "seo.features.extract_pages": "保持したいページのみを選択し、軽量ファイルとして保存します。",
    "seo.features.add_watermark": "完全にカスタマイズ可能な斜めのテキスト オーバーレイを使用して、スキャンした ID、領収書、または下書きを安全に保護します。",
    "seo.features.add_page_numbers": "カスタムの番号付け形式と動的なページ数をページにシームレスにスタンプします。",
