    "contact.faq1_q": "Meus arquivos PDF são salvos pelo Tacopdf?",
    "contact.faq1_a": "Não. Todo o processamento é feito localmente no seu navegador. Seus arquivos nunca são enviados aos nossos servidores.",
    "contact.faq2_q": "As ferramentas do Tacopdf são realmente gratuitas?",
    "contact.faq2_a": "Sim, todas as ferramentas que fornecemos são gratuitas para uso. Usamos anúncios não intrusivos para cobrir custos operacionais.",

    "tool.redact.howto.1": "Carregue o PDF contendo informações confidenciais.",
    "tool.redact.howto.2": "Desenhe retângulos pretos sobre o texto ou imagens que deseja censurar.",
    "tool.redact.howto.3": "Clique em 'Executar Redação' para aplicar o blecaute permanente.",
    "tool.redact.howto.4": "Baixe a versão editada com segurança.",
    "tool.redact.tips.1": "Uma vez redigido, o texto subjacente é completamente removido e não pode ser recuperado.",
    "tool.redact.tips.2": "Sempre verifique suas redações na visualização ao vivo antes de salvar o documento final.",
    "tool.redact.clear_page": "Limpar página",
    "tool.redact.edit_page": "Editar página",
    "tool.redact.done_edit": "Edição concluída",
    "faq.1.q": "É seguro processar arquivos PDF aqui?",
    "faq.1.a": "Absolutamente. Todos os arquivos são processados ​​localmente na memória do seu navegador usando módulos WebAssembly de alto desempenho. Nem um único byte dos seus documentos é carregado ou enviado para nossos servidores. Seus registros comerciais, pessoais e confidenciais confidenciais permanecem totalmente seguros em seu próprio dispositivo.",
    "faq.2.q": "O TacoPDF é realmente 100% gratuito?",
    "faq.2.a": "Sim, é totalmente gratuito sem taxas ocultas, sem necessidade de registro de conta, sem marcas d'água forçadas e sem limites diários de arquivos. Para cobrir os custos operacionais do nosso servidor, exibimos apenas alguns anúncios patrocinados e aceitamos doações voluntárias de nossos usuários.",
    "faq.3.q": "Posso usar este kit de ferramentas offline sem internet?",
    "faq.3.a": "Sim! Depois que o aplicativo da web é carregado no seu navegador pela primeira vez, toda a lógica de processamento do PDF é executada completamente no lado do cliente. Você pode desconectar sua Internet com segurança e continuar mesclando, dividindo, girando ou protegendo seus arquivos PDF totalmente offline.",
    "faq.4.q": "Por que este site mostra anúncios?",
    "faq.4.a": "Como uma ferramenta pública de alta utilidade que valoriza a segurança sem cobrar taxas de assinatura, os anúncios patrocinados do ajudam a financiar nossa infraestrutura básica. Otimizamos o posicionamento do anúncio para permanecer sem interrupções, agradável aos olhos e completamente separado do seu espaço de trabalho ativo.",
    "faq.5.q": "Quais formatos de arquivo são suportados?",
    "faq.5.a": "TacoPDF suporta qualquer documento PDF padrão (da versão 1.0 aos padrões mais recentes), bem como formatos de arquivo de imagem populares como PNG, JPG, JPEG e WebP para compilá-los em documentos PDF de nível profissional.",
    "faq.6.q": "Fazer uma doação me dará acesso a recursos premium?",
    "faq.6.a": "Não. O TacoPDF está empenhado em fornecer todas as ferramentas PDF gratuitamente para todos, sem exceção. A sua doação é um apoio puramente voluntário para que possamos continuar pagando os custos do servidor e desenvolvendo novos recursos. Não há recursos secretos bloqueados por um paywall.",
    "faq.7.q": "Os meus dados de pagamento de doação estão seguros?",
    "faq.7.a": "Muito seguros. Usamos plataformas de terceiros confiáveis, nomeadamente Saweria (para a Indonésia) e Ko-Fi (Internacional), como gateways de pagamento. O TacoPDF não vê, processa ou armazena os seus números de cartão de crédito ou dados bancários em nossos servidores de forma alguma.",
