    "tool_name.html_to_pdf": "HTML para PDF",
    "seo.header.title": "O kit de ferramentas PDF gratuito definitivo com zero uploads de servidor",
    "seo.header.subtitle": "TacoPDF: Editor, fusão, divisor e proteção de PDF baseado em navegador 100% seguro, rápido e privado",
    "seo.box1.title": "Processamento 100% local",
    "seo.box1.desc": "Seus documentos nunca são enviados pela internet ou armazenados em um servidor em nuvem. Todos os processos de edição, mesclagem e criptografia são executados diretamente no seu navegador usando memória local.",
    "seo.box2.title": "Tecnologia WebAssembly",
    "seo.box2.desc": "Alimentado por binários de mecanismo compilados WebAssembly (Wasm) de alto desempenho, até mesmo arquivos PDF extremamente grandes são processados ​​instantaneamente em milissegundos. Não são necessários tempos lentos de upload ou download.",
    "seo.box3.title": "Totalmente gratuito e off-line",
    "seo.box3.desc": "Totalmente gratuito para uso, sem limites de uso diário ou barreiras de assinatura paga. Basta carregar a página uma vez e você poderá continuar processando seus PDFs off-line, sem conexão com a Internet.",
    "seo.secure.title": "Otimização segura de documentos PDF sem quaisquer riscos de segurança",
    "seo.secure.p1": "No cenário digital atual, os documentos PDF geralmente contêm dados altamente confidenciais, como balanços financeiros, documentos de identidade pessoal digitalizados (IDs, passaportes, SSNs), contratos legais e registros médicos. O uso de conversores on-line típicos força você a confiar seus preciosos documentos a servidores em nuvem de terceiros, expondo-o a vulnerabilidades de violação de dados.",
    "seo.secure.p2": "<strong className=\\\"text-primary font-semibold\\\">TacoPDF</strong> estabelece um novo padrão em gerenciamento de arquivos digitais. Ao compilar localmente todo o mecanismo de processamento, garantimos que seus arquivos permanecerão totalmente em suas mãos. Esta é a maneira mais segura e privada de editar, dividir, mesclar e otimizar documentos sem acessar a Internet.",
    "seo.features.title": "Recursos excepcionais adaptados à produtividade do seu documento",
    "seo.features.merge": "Combine facilmente várias folhas de relatório ou slides em um único documento PDF conciso.",
    "seo.features.split": "Extraia páginas cruciais específicas para criar um novo documento PDF em um instante.",
    "seo.features.rotate": "Corrija digitalizações invertidas girando páginas específicas exatamente conforme necessário.",
    "seo.features.protect": "Bloqueie e criptografe arquivos PDF confidenciais localmente usando algoritmos AES padrão e seguros.",
    "seo.features.unlock": "Elimine as senhas dos seus próprios documentos para facilitar a impressão e o compartilhamento.",
    "seo.features.redact": "Oculte e censure permanentemente textos ou imagens confidenciais para proteger informações confidenciais.",
    "seo.features.image_to_pdf": "Converta instantaneamente imagens PNG, JPG, JPEG e WebP em arquivos PDF formais prontos para impressão.",
    "seo.features.pdf_to_image": "Extraia e renderize cada página do seu PDF em fotos de imagens de alta qualidade.",
    "seo.features.delete_pages": "Corte de forma limpa páginas em branco ou indesejadas da estrutura do seu documento.",
    "seo.features.extract_pages": "Escolha apenas as páginas que deseja manter e salve-as como um arquivo leve.",
    "seo.features.add_watermark": "Proteja IDs, recibos ou rascunhos digitalizados com sobreposições de texto diagonais totalmente personalizáveis.",
    "seo.features.add_page_numbers": "Carimbe formatos de numeração personalizados e contagens dinâmicas de páginas perfeitamente em suas páginas.",
