    "contact.faq": "Foire aux questions (FAQ)",
    "contact.faq1_q": "Mes fichiers PDF sont-ils enregistrés par Tacopdf?",
    "contact.faq1_a": "Non. Tout le traitement est effectué localement dans votre navigateur. Vos fichiers ne sont jamais téléchargés sur nos serveurs.",
    "contact.faq2_q": "Les outils Tacopdf sont-ils vraiment gratuits?",
    "contact.faq2_a": "Oui, tous les outils sont gratuits. Nous utilisons des publicités non intrusives pour couvrir les coûts d'exploitation.",

    "tool.redact.howto.1": "Téléchargez le PDF contenant des informations sensibles.",
    "tool.redact.howto.2": "Dessinez des rectangles noirs sur le texte ou les images que vous souhaitez censurer.",
    "tool.redact.howto.3": "Cliquez sur 'Exécuter Caviarder' pour appliquer le noircissement définitif.",
    "tool.redact.howto.4": "Téléchargez la version expurgée en toute sécurité.",
    "tool.redact.tips.1": "Une fois expurgé, le texte sous-jacent est complètement supprimé et ne peut pas être récupéré.",
    "tool.redact.tips.2": "Vérifiez toujours vos caviardages dans l'aperçu en direct avant d'enregistrer le document final.",
    "tool.redact.clear_page": "Effacer la page",
    "tool.redact.edit_page": "Modifier la page",
    "tool.redact.done_edit": "Terminé",
    "faq.1.q": "Est-il sûr de traiter des fichiers PDF ici ?",
    "faq.1.a": "Absolument. Tous les fichiers sont traités localement dans la mémoire de votre navigateur. Pas un seul octet n est envoyé sur nos serveurs.",
    "faq.2.q": "TacoPDF est-il vraiment 100% gratuit ?",
    "faq.2.a": "Oui, c'est totalement gratuit sans frais cachés, sans inscription de compte requise, sans filigrane imposé et sans limite quotidienne de fichiers. Pour couvrir les coûts d'exploitation de nos serveurs, nous affichons uniquement quelques annonces sponsorisées et acceptons les dons volontaires de nos utilisateurs.",
    "faq.3.q": "Puis-je utiliser cet outil hors ligne sans Internet ?",
    "faq.3.a": "Oui ! Une fois l application Web chargée, tout le traitement s effectue côté client. Vous pouvez vous déconnecter et continuer à travailler.",
    "faq.4.q": "Pourquoi ce site affiche-t-il des publicités ?",
    "faq.4.a": "En tant qu outil gratuit, les annonces aident à financer notre infrastructure.",
    "faq.5.q": "Quels formats de fichiers sont pris en charge ?",
    "faq.5.a": "Nous prenons en charge tous les documents PDF standard, ainsi que les formats d image populaires tels que PNG, JPG, JPEG et WebP.",
    "faq.6.q": "Faire un don me donnera-t-il accès à des fonctionnalités premium ?",
    "faq.6.a": "Non. TacoPDF s'engage à fournir tous les outils PDF gratuitement à tout le monde sans exception. Votre don est un soutien purement volontaire afin que nous puissions continuer à payer les frais de serveur et à développer de nouvelles fonctionnalités. Il n'y a pas de fonctionnalités secrètes bloquées derrière un paiement.",
    "faq.7.q": "Mes données de paiement de don sont-elles sécurisées ?",
    "faq.7.a": "Très sécurisées. Nous utilisons des plateformes tierces de confiance, à savoir Saweria (pour l'Indonésie) et Ko-Fi (International), comme passerelles de paiement. TacoPDF ne voit, ne traite ni ne stocke en aucun cas vos numéros de carte de crédit ou vos coordonnées bancaires sur nos serveurs.",
