    "tool.image-to-pdf.tip.title": "🖼️ IMAGE EN PDF",
    "tool.image-to-pdf.tip.desc": "Importez des images JPG, PNG ou WEBP — plusieurs à la fois ! Glissez les cartes pour les réorganiser avant la conversion. Choisissez la taille de page : A4, Letter ou Ajuster à l'image.",
    "tool.pdf-to-image.tip.title": "🖼️ IDÉAL POUR LES RÉSEAUX SOCIAUX",
    "tool.pdf-to-image.tip.desc": "Les fichiers PDF ne peuvent pas être publiés sur les flux sociaux. Convertissez en JPG/PNG haute résolution ici pour qu'ils puissent être facilement partagés !",
    "tool.html-to-pdf.tip.title": "🌐 FACTURES ET REÇUS",
    "tool.html-to-pdf.tip.desc": "Très utile pour coller du code de reçu brut ou des articles Web et les transformer en documents PDF soignés et prêts à imprimer.",
    "tool.add-watermark.tip.title": "©️ PROTÉGEZ VOTRE TRAVAIL",
    "tool.add-watermark.tip.desc": "Utilisez un faible niveau de transparence (opacité) afin que le tampon de droit d'auteur protège le document sans interrompre le contenu textuel d'origine.",
    "tool.add-page-numbers.tip.title": "🔢 NORME OFFICIELLE",
